enum DateTime64 {
    Nat,
    Valid(i64),
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // For each element in the input vector,
    // output true if it is Nat,
    // false if it is Valid(_).
    x.into_iter()
        .map(|elem| matches!(elem, DateTime64::Nat))
        .collect()
}